      border-radius: 6px; padding: .55rem 1rem; cursor: pointer; font-size: .95rem;
    }
    button:hover { filter: brightness(1.1); }
    .patch-btn { background: var(--pulse); font-size: .8rem; padding: .4rem .7rem; }

    /* === думающий СР === */
    .thinking {
      display: flex; align-items: center; gap: .5rem;
      color: var(--subtle); font-size: .9rem;
      margin: .5rem 0;
    }
    .thinking .logo {
      width: 18px; height: 18px;
      background: url('data:image/svg+xml;base64,') center/contain no-repeat;
      animation: spin 1.2s linear infinite;
    }
    @keyframes spin { to { transform: rotate(360deg); } }
    .dots::after {
      content: ''; display: inline-block; width: 2ch;
      animation: dots 1.5s steps(4,end) infinite;
    }
    @keyframes dots { 0% { content: ''; } 25% { content: '.'; } 50% { content: '..'; } 75% { content: '...'; } }

    /* === единые кнопки кода === */
    .code-btn {
      background: var(--surface);
      border: 1px solid #30363d;
      color: var(--menu-highlight);
      font-size: .75rem;
      padding: .3rem .5rem;
      border-radius: 4px;
      cursor: pointer;
      white-space: nowrap;
