    .code-btn:hover { border-color: var(--accent); }

    aside#side {
      position: fixed; right: 0; top: 3.2rem; bottom: 0; width: 220px;
      background: var(--surface); border-left: 1px solid #30363d;
      padding: 1rem .75rem; overflow-y: auto; font-size: .85rem;
    }
    aside#side h3 {
      margin: .75rem 0 .25rem; font-size: .9rem; color: var(--menu-highlight);
