<body>
  <header>
    <span class="pulse" title="ядро живо"></span>
    <span>🌊 Мандала – инженерный чат</span>
  </header>

  <main id="chat"></main>

  <footer>
    <textarea id="input" placeholder="Ваше сообщение…" rows="2"></textarea>
    <button onclick="send()">Отправить</button>
    <button class="patch-btn" onclick="sendPatch()">Patch</button>
  </footer>

  <aside id="side">
    <h3>🌱 Семена</h3><a href="#" onclick="loadSide('seeds')">Показать</a>
    <h3>🚩 Вехи</h3><a href="#" onclick="loadSide('milestones')">Показать</a>
    <h3>⚡ Статус</h3><a href="#" onclick="loadSide('status')">Показать</a>
  </aside>

  <script>
    const wsUrl = `${location.protocol === 'https:' ? 'wss:' : 'ws:'}//${location.host}/ws`;
    const ws = new WebSocket(wsUrl);
    const chat = document.getElementById('chat');
    const input = document.getElementById('input');

    ws.onmessage = e => { hideThinking(); append('sr', e.data); };
    ws.onclose = () => { hideThinking(); append('sr', '🔗 связь прервана'); };

    function append(who, txt) {
      const div = document.createElement('div');
      div.className = 'msg ' + who;
      div.innerHTML = txt; // позволяет вставлять <button class="code-btn">...
      chat.appendChild(div);
      chat.scrollTop = chat.scrollHeight;
    }
    function send() {
      if (!input.value.trim()) return;
      append('you', input.value);
      showThinking();
      ws.send(input.value);
      input.value = '';
    }
    function sendPatch() {
      const file = prompt('Перетащи сюда .json патч или вставь его текст:');
      if (!file) return;
      fetch('/patch/apply', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: file })
        .then(r => r.json())
        .then(d => append('sr', '<pre class="code-btn">' + JSON.stringify(d, null, 2) + '</pre>'))
        .catch(err => append('sr', String(err)));
    }
    function showThinking() {
      if (document.querySelector('.thinking')) return;
      const wrap = document.createElement('div');
      wrap.className = 'thinking';
      wrap.innerHTML = '<span class="logo"></span>СР думает<span class="dots"></span>';
      chat.appendChild(wrap);
      chat.scrollTop = chat.scrollHeight;
    }
    function hideThinking() {
      document.querySelectorAll('.thinking').forEach(el => el.remove());
    }
    input.addEventListener('keydown', e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send(); } });
    async function loadSide(kind) {
      const res = await fetch('/api/' + kind);
      const data = await res.json();
      append('sr', '<pre class="code-btn">' + JSON.stringify(data, null, 2) + '</pre>');
    }
  </script>
</body>
</html>"
    }
